 const buildExportData=async(allTime=false)=>{const inRange=value=>allTime||(!exportRange.from||String(value||'').slice(0,10)>=exportRange.from)&&(!exportRange.to||String(value||'').slice(0,10)<=exportRange.to);const [salesAll,saleItemsAll,productsAll,batchesAll,categoriesAll,profiles,settings,suppliersAll,purchasesAll,purchasePaymentsAll,customersAll,customerPaymentsAll,productChangesAll,stockAdjustmentsAll,supplierReturnsAll,supplierReturnItemsAll,writeoffsAll,restockOrdersAll]=await Promise.all([fetchTable('sales'),fetchTable('sale_items'),fetchTable('products'),fetchTable('batches'),fetchTable('categories'),fetchTable('profiles'),fetchTable('shop_settings'),fetchTable('suppliers'),fetchTable('purchases'),fetchTable('purchase_payments'),supabase.rpc('owner_customer_records').then(r=>{if(r.error)throw r.error;return r.data||[]}),fetchTable('customer_payments'),fetchTable('product_changes'),fetchTable('stock_adjustments'),fetchTable('supplier_returns'),fetchTable('supplier_return_items'),fetchTable('stock_writeoffs'),fetchTable('restock_orders')]);const sales=salesAll.filter(s=>inRange(s.created_at));const saleIds=new Set(sales.map(s=>s.id));const saleItems=saleItemsAll.filter(i=>saleIds.has(i.sale_id));const productById=new Map(productsAll.map(p=>[p.id,p]));const batches=batchesAll.map(b=>({product_id:b.product_id,barcode:productById.get(b.product_id)?.barcode,product_name:productById.get(b.product_id)?.name,...b}));const expiredDate=todayISO();const expiries=batches.filter(b=>b.expiry_date&&b.expiry_date<=new Date(Date.now()+30*86400000).toISOString().slice(0,10));const unitsByProduct=new Map();batchesAll.filter(b=>!b.expiry_date||b.expiry_date>=expiredDate).forEach(b=>unitsByProduct.set(b.product_id,(unitsByProduct.get(b.product_id)||0)+Number(b.units||0)));const lowStock=productsAll.filter(p=>(unitsByProduct.get(p.id)||0)<=Number(p.low_stock_limit??5)).map(p=>({product_id:p.id,barcode:p.barcode,name:p.name,category:p.category,mrp:p.mrp,units:unitsByProduct.get(p.id)||0,low_stock_limit:p.low_stock_limit}));const purchasePaid=new Map();purchasePaymentsAll.filter(x=>!x.canceled_at).forEach(x=>purchasePaid.set(x.purchase_id,(purchasePaid.get(x.purchase_id)||0)+Number(x.amount||0)));const returnCredits=new Map();supplierReturnsAll.filter(r=>r.status==='Credited'&&r.settlement==='reduce_owed').forEach(r=>returnCredits.set(r.supplier_id,(returnCredits.get(r.supplier_id)||0)+Number(r.receipt_amount||0)));const purchaseStatusAll=purchasesAll.filter(p=>!p.canceled_at).sort((a,b)=>String(a.bill_date).localeCompare(String(b.bill_date))).map(p=>{const gross=Math.max(0,Number(p.total)-(purchasePaid.get(p.id)||0)),credit=Math.min(gross,returnCredits.get(p.supplier_id)||0);returnCredits.set(p.supplier_id,Math.max(0,(returnCredits.get(p.supplier_id)||0)-credit));const amount_paid=Number(purchasePaid.get(p.id)||0)+credit,balance=Math.max(0,Number(p.total)-amount_paid);return {...p,amount_paid,balance,status:balance===0?'Paid':amount_paid>0?'Part paid':'Not paid',supplier_credit_applied:credit}});const purchases=purchaseStatusAll.filter(p=>inRange(p.bill_date));const supplierPayments=purchasePaymentsAll.filter(p=>inRange(p.paid_on));const customers=new Set(customersAll.map(c=>c.id));const activeCreditSales=salesAll.filter(s=>s.payment_mode==='credit'&&s.customer_id&&!s.canceled_at);const activeIds=new Set(activeCreditSales.map(s=>s.id));const customerPayments=customerPaymentsAll.filter(p=>inRange(p.paid_on));const events=[...activeCreditSales.map(s=>({customer_id:s.customer_id,date:s.created_at.slice(0,10),type:'Credit bill',reference:s.bill_number?`Bill ${s.bill_number}`:s.id,debit:Number(s.total),credit:0})),...customerPaymentsAll.filter(p=>!p.canceled_at&&(!p.sale_id||activeIds.has(p.sale_id))).map(p=>({customer_id:p.customer_id,date:p.paid_on,type:'Payment received',reference:p.sale_id?(salesAll.find(s=>s.id===p.sale_id)?.bill_number?`Bill ${salesAll.find(s=>s.id===p.sale_id).bill_number}`:p.sale_id):'Account payment',debit:0,credit:Number(p.amount)}))].sort((a,b)=>a.date.localeCompare(b.date));const ledgerBalances=new Map();const ledgerAll=events.map(e=>{const balance=(ledgerBalances.get(e.customer_id)||0)+e.debit-e.credit;ledgerBalances.set(e.customer_id,balance);return {...e,customer_name:customersAll.find(c=>c.id===e.customer_id)?.name||'',phone:customersAll.find(c=>c.id===e.customer_id)?.phone||'',balance}});const customerLedger=ledgerAll.filter(e=>inRange(e.date));const filteredCustomerPayments=customerPayments;const productsNoBatches=productsAll;return {products:productsNoBatches,batches,sales,sale_items:saleItems,categories:categoriesAll,profiles,shop_settings:settings,expiry_list:expiries,low_stock_list:lowStock,suppliers:suppliersAll,purchases,supplier_payments:supplierPayments,supplier_returns:supplierReturnsAll.filter(r=>inRange(r.created_at)),supplier_return_items:supplierReturnItemsAll.filter(i=>inRange(i.created_at)),stock_writeoffs:writeoffsAll.filter(w=>inRange(w.written_off_at)),restock_orders:restockOrdersAll.filter(r=>inRange(r.created_at)),customers:customersAll,customer_payments:filteredCustomerPayments,customer_ledger:customerLedger,product_changes:productChangesAll,stock_adjustments:stockAdjustmentsAll}};
 const serializeCsv=(rows,type)=>{const defaults={products:['id','barcode','name','category','mrp','selling_price','cost_price','mrp_confirmed','hidden','unit_type','low_stock_limit','created_at'],batches:['id','product_id','barcode','product_name','mfg_date','expiry_date','units','cost_price','purchase_id','discounted','deleted_at','created_at'],sales:['id','bill_number','created_at','subtotal','discount','total','payment_mode','customer_id','customer_name','customer_phone','staff_id','canceled_at'],sale_items:['id','sale_id','product_id','batch_id','quantity','price','mrp','cost_price','gst_rate'],expiry_list:['id','product_id','barcode','product_name','expiry_date','units'],low_stock_list:['product_id','barcode','name','category','mrp','selling_price','units','low_stock_limit'],suppliers:['id','name','phone','created_at'],purchases:['id','supplier_id','bill_number','bill_date','total','amount_paid','balance','status','remind_on','note','created_at','canceled_at'],supplier_payments:['id','purchase_id','amount','paid_on','mode','note','created_at','canceled_at'],customers:['id','name','phone','created_at'],customer_payments:['id','customer_id','sale_id','amount','paid_on','mode','note','created_at','canceled_at'],customer_ledger:['customer_id','customer_name','phone','date','type','reference','debit','credit','balance'],product_changes:['id','product_id','product_name','changed_by','field_name','old_value','new_value','created_at'],stock_adjustments:['id','batch_id','product_id','product_name','batch_mfg_date','batch_expiry_date','units_before','delta','reason','who','created_at'],supplier_returns:['id','supplier_id','supplier_name','status','reason','note','receipt_number','returned_on','receipt_amount','settlement','created_by','created_at'],supplier_return_items:['id','return_id','batch_id','product_id','product_name','units','expiry_date','buying_price','expected_credit','created_at'],stock_writeoffs:['id','batch_id','product_id','product_name','units','buying_price','value_lost','reason','written_off_by','written_off_at'],restock_orders:['id','product_id','requested_units','status','created_by','created_at','completed_at']};const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))];const headers=cols.length?cols:(defaults[type]||[]);const dateColumn=h=>/(date|_on|_at)$/i.test(h);const cell=(v,h)=>{if(v==null)return '';if(dateColumn(h)&&typeof v==='string'&&v){const d=new Date(/^\d{4}-\d\d-\d\d$/.test(v)?`${v}T00:00:00`:v);if(!Number.isNaN(d.valueOf()))return d.toLocaleDateString('en-GB')}return String(v)};return '\ufeff'+[headers.join(','),...rows.map(r=>headers.map(c=>`"${cell(r[c],c).replaceAll('"','""')}"`).join(','))].join('\r\n')};
 const exportFile=async(type,format)=>{if(role!=='owner')return notify('Owner access only.');try{const datasets=await buildExportData(type==='full_backup');const rows=type==='full_backup'?Object.values(datasets).flat():datasets[type]||[];const stem=type.replaceAll('_','-');if(format==='csv'){download(new Blob([serializeCsv(rows,type)],{type:'text/csv;charset=utf-8'}),`sathvika-${stem}.csv`)}else{const X=await import('xlsx');const wb=X.utils.book_new();const addSheet=(sheetName,items)=>{const headers=[...new Set(items.flatMap(r=>Object.keys(r)))];const values=items.map(r=>headers.map(h=>{let v=r[h];if(v==null)return '';if((/(date|_on|_at)$/i.test(h))&&typeof v==='string'&&v){const dt=new Date(/^\d{4}-\d\d-\d\d$/.test(v)?`${v}T00:00:00`:v);return Number.isNaN(dt.valueOf())?v:dt}return v}));const ws=X.utils.aoa_to_sheet([headers,...values]);ws['!cols']=headers.map(h=>({wch:Math.min(30,Math.max(14,h.length+2))}));headers.forEach((h,c)=>{for(let r=1;r<=values.length;r++){const cell=ws[X.utils.encode_cell({r,c})];if(!cell)continue;if(/(date|_on|_at)$/i.test(h))cell.z=/_at$/i.test(h)?'dd-mm-yyyy hh:mm':'dd-mm-yyyy';if(/mrp|price|cost|total|subtotal|discount|value|amount|balance|owed|paid|debit|credit/i.test(h))cell.z='₹#,##0.00'}});X.utils.book_append_sheet(wb,ws,sheetName.slice(0,31))};if(type==='full_backup'){Object.entries(datasets).forEach(([name,items])=>addSheet(name,items))}else addSheet(type,rows);download(new Blob([X.write(wb,{bookType:'xlsx',type:'array'})],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),`sathvika-${stem}.xlsx`)}notify(rows.length?`Downloaded ${rows.length} ${type.replaceAll('_',' ')} rows.`:`Download ready: no ${type.replaceAll('_',' ')} records match this range.`)}catch(err){notify('Export failed: '+err.message)}};

 const loadReportData=async()=>{try{const [s,items]=await Promise.all([fetchTable('sales'),fetchTable('sale_items')]);setReportSales(s);setReportItems(items)}catch(err){notify('Could not load reports: '+err.message)}};
 const periodStart=()=>{const now=new Date();if(filter==='Custom')return customRange.from?new Date(customRange.from+'T00:00:00'):new Date(0);const d=new Date(now);d.setHours(0,0,0,0);if(filter==='7 days')d.setDate(d.getDate()-6);if(filter==='30 days')d.setDate(d.getDate()-29);return d};
