 const periodSaleIds=new Set(filteredReportSales.map(s=>s.id));const filteredReportItems=reportItems.filter(i=>periodSaleIds.has(i.sale_id));const productById=new Map(products.map(p=>[p.id,p]));const saleById=new Map(reportSales.map(s=>[s.id,s]));
 const reportTotal=filteredReportSales.reduce((n,s)=>n+Number(s.total||0),0);const reportAvg=filteredReportSales.length?reportTotal/filteredReportSales.length:0;const cashSales=filteredReportSales.filter(s=>s.payment_mode==='cash').reduce((n,s)=>n+Number(s.total||0),0);const upiSales=filteredReportSales.filter(s=>s.payment_mode==='upi').reduce((n,s)=>n+Number(s.total||0),0);const creditGiven=filteredReportSales.filter(s=>s.payment_mode==='credit').reduce((n,s)=>n+Number(s.total||0),0);const customerMoneyReceived=(data.customerPayments||[]).filter(p=>!p.canceled_at&&new Date((p.paid_on||p.created_at||'').slice(0,10)+'T00:00:00')>=periodStart()&&new Date((p.paid_on||p.created_at||'').slice(0,10)+'T00:00:00')<=periodEnd()).reduce((n,p)=>n+Number(p.amount||0),0);
 const reportProfit=filteredReportItems.length&&filteredReportItems.every(i=>i.cost_price!==null&&i.cost_price!==undefined)?filteredReportItems.reduce((n,i)=>n+(Number(i.price)-Number(i.cost_price))*Number(i.quantity),0)-filteredReportSales.reduce((n,s)=>n+Number(s.discount||0),0):null;
 const bestSellers=(()=>{const by=new Map();filteredReportItems.forEach(i=>{const p=productById.get(i.product_id);const x=by.get(i.product_id)||{name:p?.name||'Product',units:0,revenue:0};x.units+=Number(i.quantity);x.revenue+=Number(i.price)*Number(i.quantity);by.set(i.product_id,x)});return [...by.values()].sort((a,b)=>bestMode==='units'?b.units-a.units:b.revenue-a.revenue).slice(0,10)})();
 const categoryChart=(()=>{const by=new Map();filteredReportItems.forEach(i=>{const p=productById.get(i.product_id);const key=p?.category||'Other';by.set(key,(by.get(key)||0)+Number(i.price)*Number(i.quantity))});return [...by].map(([name,value])=>({name,value}))})();
 const dayChart=(()=>{const by=new Map();filteredReportSales.forEach(s=>{const k=new Date(s.created_at).toLocaleDateString('en-IN',{day:'numeric',month:'short'});by.set(k,(by.get(k)||0)+Number(s.total))});return [...by].map(([day,sales])=>({day,sales}))})();
