 const salesLast30=reportItems.filter(i=>{const sale=saleById.get(i.sale_id);return sale&&!sale.canceled_at&&new Date(sale.created_at)>=new Date(Date.now()-30*86400000)});
 const recentProductIds=new Set(salesLast30.map(i=>i.product_id));const recentUnits=new Map();salesLast30.forEach(i=>recentUnits.set(i.product_id,(recentUnits.get(i.product_id)||0)+Number(i.quantity)));const slowProducts=products.filter(p=>!recentProductIds.has(p.id));const firstBillDate=reportSales.filter(s=>!s.canceled_at).map(s=>new Date(s.created_at)).sort((a,b)=>a-b)[0];const has30DayHistory=!!firstBillDate&&Date.now()-firstBillDate.getTime()>=30*86400000;
 const reorderProducts=low.map(p=>{const sold=recentUnits.get(p.id)||0,unitsLeft=allUnits(p),limit=Number(p.low_stock_limit??5);return {...p,sold,unitsLeft,limit,shortage:Math.max(0,limit-unitsLeft),speed:sold/30,daysCover:sold?Math.round(unitsLeft/(sold/30)):Infinity}}).sort((a,b)=>recentUnits.size?b.speed-a.speed:b.shortage-a.shortage);
