 const bulkSetCategoryLimit=async cat=>{if(role!=='owner')return notify('Only the owner can change stock limits.');const raw=prompt(`Set the low-stock limit for every ${cat} product:`,String(products.find(p=>p.category===cat)?.low_stock_limit??5));if(raw===null)return;const limit=Number(raw);if(!Number.isInteger(limit)||limit<0)return notify('Enter a whole number zero or greater.');if(supabase){const {error}=await supabase.from('products').update({low_stock_limit:limit}).eq('category',cat);if(error)return notify(error.message)}setData(d=>({...d,products:d.products.map(p=>p.category===cat?{...p,low_stock_limit:limit}:p)}));notify(`Low-stock limit ${limit} applied to ${cat}.`)};
