 const savePurchasePayment=async()=>{if(role!=='owner'||!purchasePayment)return;const purchase=pendingPurchases.find(p=>p.id===purchasePayment);const amount=Number(purchasePayForm.amount);if(!purchase||!amount||amount<0||amount>purchase.balance)return notify('Enter an amount up to the unpaid balance.');const {data:payment,error}=await supabase.from('purchase_payments').insert({purchase_id:purchase.id,amount,paid_on:purchasePayForm.paid_on,mode:purchasePayForm.mode,note:purchasePayForm.note||null,created_by:userId}).select().single();if(error)return notify(error.message);setData(d=>({...d,purchasePayments:[...(d.purchasePayments||[]),payment]}));setPurchasePayment(null);setPurchasePayForm({amount:'',paid_on:todayISO(),mode:'cash',note:''});notify('Supplier payment saved')};
 const cancelPurchasePayment=async payment=>{if(role!=='owner'||!confirm(`Cancel this ${fmt(payment.amount)} payment? The record will be retained.`))return;const {error}=await supabase.from('purchase_payments').update({canceled_at:new Date().toISOString()}).eq('id',payment.id);if(error)return notify(error.message);setData(d=>({...d,purchasePayments:d.purchasePayments.map(p=>p.id===payment.id?{...p,canceled_at:new Date().toISOString()}:p)}));notify('Payment cancelled')};
 const editPurchaseBill=async purchase=>{if(role!=='owner')return;const bill_number=prompt('Bill number',purchase.bill_number||'');if(bill_number===null)return;const bill_date=prompt('Bill date (YYYY-MM-DD)',purchase.bill_date)||purchase.bill_date;const totalText=prompt('Correct bill total',String(purchase.total));if(totalText===null)return;const total=Number(totalText);if(!Number.isFinite(total)||total<0)return notify('Enter a valid bill total.');const paid=purchasePaidById.get(purchase.id)||0;if(total<paid)return notify('Bill total cannot be less than payments already recorded.');const remind=prompt('Remind on (YYYY-MM-DD), or leave blank',purchase.remind_on||'');if(remind===null)return;const {error}=await supabase.from('purchases').update({bill_number:bill_number||null,bill_date,total,remind_on:remind||null}).eq('id',purchase.id);if(error)return notify(error.message);await reloadPurchases();notify('Purchase bill corrected')};
 const cancelPurchaseBill=async purchase=>{if(role!=='owner')return;const removeStock=confirm(`Cancel bill ${purchase.bill_number||''} from ${purchase.supplier?.name||'supplier'}?\n\nOK = also remove remaining linked stock. Cancel = cancel the bill but keep stock.`);if(!confirm('Confirm cancellation of this purchase bill?'))return;const {error}=await supabase.from('purchases').update({canceled_at:new Date().toISOString()}).eq('id',purchase.id);if(error)return notify(error.message);if(removeStock){const batches=products.flatMap(p=>p.batches.filter(b=>b.purchase_id===purchase.id&&b.units>0));for(const b of batches){const {error:stockError}=await supabase.from('batches').update({units:0}).eq('id',b.id);if(stockError)return notify('Bill cancelled, but stock update failed: '+stockError.message)}setData(d=>({...d,purchases:d.purchases.map(p=>p.id===purchase.id?{...p,canceled_at:new Date().toISOString()}:p),products:d.products.map(p=>({...p,batches:p.batches.map(b=>b.purchase_id===purchase.id?{...b,units:0}:b)}))}))}else setData(d=>({...d,purchases:d.purchases.map(p=>p.id===purchase.id?{...p,canceled_at:new Date().toISOString()}:p)}));notify('Purchase bill cancelled')};
