 if(!logged)return <div className="login-wrap"><div className="login-card"><img className="login-logo" src="/logo.png" alt="Sathvika M V shop logo"/><div className="eyebrow">SATHVIKA M V · PROVISION STORE</div>{!supabase?<><h1>Connect your store database</h1><p className="muted">Add your Supabase project URL and public anon key to <code>.env.local</code>, then apply <code>supabase/schema.sql</code>.</p><div className="csv-columns"><b>Required setup</b><span>VITE_SUPABASE_URL<br/>VITE_SUPABASE_ANON_KEY</span></div></>:ownerExists===false?<><h1>Create owner account</h1><p className="muted">This one-time setup is available only while the store has no owner.</p><form onSubmit={createOwner}><label>Your name<input type="text" autoComplete="name" required value={form.ownerName||''} onChange={e=>updateForm('ownerName',e.target.value)} placeholder="Store owner"/></label><label>{t.email}<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>{t.password}<input type="password" autoComplete="new-password" minLength="8" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></label><button className="btn primary full" type="submit">Create owner account<ChevronRight size={19}/></button></form><p className="login-foot"><ShieldCheck size={15}/> Only the first account can become owner.</p></>:<><h1>{authMode==='forgot'?'Reset your password':authMode==='password-reset'?'Choose a new password':'Sign in to your store'}</h1><p className="muted">{authMode==='forgot'?'We will email you a secure reset link.':authMode==='password-reset'?'Choose a new password for your account.':'Your stock is shared securely with your team.'}</p><form onSubmit={authMode==='forgot'?e=>{e.preventDefault();forgotPassword()}:authMode==='password-reset'?updatePassword:doLogin}><label>{t.email}<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label>{authMode!=='forgot'&&<label>{authMode==='password-reset'?'New password':t.password}<input type="password" autoComplete={authMode==='password-reset'?'new-password':'current-password'} required minLength="8" value={password} onChange={e=>setPassword(e.target.value)} placeholder={authMode==='password-reset'?'At least 8 characters':'Your password'}/></label>}<button className="btn primary full" type="submit">{authMode==='forgot'?'Send reset email':authMode==='password-reset'?'Save new password':t.continue}<ChevronRight size={19}/></button></form>{authMode==='forgot'||authMode==='password-reset'?<button className="text-action" onClick={()=>setAuthMode('login')}>Back to sign in</button>:<button className="text-action" onClick={()=>setAuthMode('forgot')}>Forgot password?</button>}{ownerExists===null&&<button className="text-action" onClick={()=>setOwnerExists(true)}>Already set up? Sign in</button>}</>}<div className="login-links">{supabase?'Secure Supabase authentication':'Setup needed'}<button onClick={()=>setLang(lang==='en'?'ta':'en')}><Languages size={15}/> {lang==='en'?'தமிழ்':'English'}</button></div></div></div>;
 const header=<header className="topbar"><div className="brand"><img className="brand-logo" src="/logo.png" alt=""/><div><b>Sathvika M V</b><small>Provision Store</small></div></div><div className="header-right">{offline&&<span className="offline-pill"><WifiOff size={14}/> Offline</span>}<button className="user-avatar" onClick={()=>{setTab('More');setScreen('')}}>{(displayName||email||'S').slice(0,1).toUpperCase()}</button></div></header>;
 const expiryTag=(date)=>{if(!date)return <span className="expiry amber">Check dates</span>;let days=daysTo(date);return <span className={`expiry ${days<0?'red':days<7?'red':days<=expiringSoonWindow?'amber':'green'}`}>{days<0?`Expired ${Math.abs(days)}d`:days<=expiringSoonWindow?`Expiring · ${days}d`:`${days} days left`}</span>};
 const productStatusTags=p=>{const bs=(p.batches||[]).filter(b=>b.units>0);const expired=bs.some(b=>b.expiry_date&&b.expiry_date<todayISO());const missing=bs.some(b=>!b.mfg_date||!b.expiry_date);const nearest=bs.filter(b=>b.expiry_date&&b.expiry_date>=todayISO()).sort((a,b)=>a.expiry_date.localeCompare(b.expiry_date))[0];return <div className="prod-expiry-tags">{expired&&<span className="expiry red">Expired</span>}{nearest&&expiryTag(nearest.expiry_date)}{missing&&<span className="expiry amber">Check dates</span>}</div>};
 const previewBulkChange=()=>{if(role!=='owner')return notify('Only the owner can bulk edit products.');if(!bulkSelection.length)return notify('Select at least one product.');if(bulkFields.mode==='percent'&&(!Number.isFinite(Number(bulkFields.percent))||Number(bulkFields.percent)<0||Number(bulkFields.percent)>100))return notify('Enter a percent from zero to 100.');if(bulkFields.mode==='limit'&&(!Number.isInteger(Number(bulkFields.low_stock_limit))||Number(bulkFields.low_stock_limit)<0))return notify('Enter a whole low-stock limit of zero or more.');const selectedProducts=products.filter(p=>bulkSelection.includes(p.id));const preview=selectedProducts.map(p=>{let changes={},before='',after='';if(bulkFields.mode==='category'){changes.category=bulkFields.category;before=p.category;after=changes.category}else if(bulkFields.mode==='limit'){changes.low_stock_limit=Number(bulkFields.low_stock_limit);before=p.low_stock_limit??5;after=changes.low_stock_limit}else if(bulkFields.mode==='supplier'){changes.default_supplier_id=bulkFields.supplier_id||null;before=suppliers.find(v=>v.id===p.default_supplier_id)?.name||'No supplier';after=suppliers.find(v=>v.id===changes.default_supplier_id)?.name||'No supplier'}else if(bulkFields.mode==='mrp'){changes.selling_price=Number(p.mrp);changes.mrp_confirmed=true;before=sellPrice(p);after=changes.selling_price}else if(bulkFields.mode==='percent'){changes.selling_price=Math.min(Number(p.mrp),Math.round(Number(p.mrp)*(1-Number(bulkFields.percent)/100)*100)/100);changes.mrp_confirmed=!!p.mrp_confirmed;before=sellPrice(p);after=changes.selling_price}return {...p,changes,before:String(before),after:String(after)}});setBulkPreview(preview)};
 const applyBulkChange=async()=>{if(role!=='owner'||!bulkPreview?.length)return;if(!navigator.onLine||!supabase)return notify('Connect to the internet before saving bulk changes. Your preview is still available.');const savedAt=Date.now(),before=bulkPreview.map(p=>({id:p.id,values:Object.fromEntries(Object.keys(p.changes).map(k=>[k,p[k]??null]))}));const writes=await Promise.all(bulkPreview.map(item=>supabase.from('products').update(item.changes).eq('id',item.id)));const failed=writes.find(result=>result.error);if(failed){await Promise.all(bulkPreview.map(item=>{const old=before.find(x=>x.id===item.id);return supabase.from('products').update(old.values).eq('id',item.id)}));return notify('Bulk edit failed and previous values were restored: '+failed.error.message)}const audit=bulkPreview.flatMap(p=>Object.entries(p.changes).filter(([field,value])=>String(p[field]??'')!==String(value??'')).map(([field,value])=>({product_id:p.id,product_name:p.name,changed_by:userId,field_name:field,old_value:p[field]==null?null:String(p[field]),new_value:value==null?null:String(value)})));let auditWarning='';if(audit.length){const {error}=await supabase.from('product_changes').insert(audit);if(error)auditWarning='Bulk edit saved, but audit history failed: '+error.message}setData(d=>({...d,products:d.products.map(p=>{const row=bulkPreview.find(x=>x.id===p.id);return row?{...p,...row.changes}:p})}));setBulkUndo({savedAt,expires:savedAt+600000,before});setTimeout(()=>setBulkUndo(x=>x?.savedAt===savedAt&&Date.now()>=x.expires?null:x),600000);setBulkPreview(null);setBulkSelection([]);setBulkFields(v=>({...v,mode:''}));notify(auditWarning||'Bulk edit saved')};
 const undoBulkChange=async()=>{if(!bulkUndo||Date.now()>bulkUndo.expires)return notify('The 10-minute undo period has expired.');if(!supabase||!navigator.onLine)return notify('Connect to the internet to undo; nothing was changed.');const reverseAudit=[];for(const item of bulkUndo.before){const current=products.find(p=>p.id===item.id);const {error}=await supabase.from('products').update(item.values).eq('id',item.id);if(error)return notify('Undo stopped: '+error.message);for(const [field,value] of Object.entries(item.values))if(String(current?.[field]??'')!==String(value??''))reverseAudit.push({product_id:item.id,product_name:current?.name||'Product',changed_by:userId,field_name:field,old_value:current?.[field]==null?null:String(current[field]),new_value:value==null?null:String(value)})}let auditWarning='';if(reverseAudit.length){const {error}=await supabase.from('product_changes').insert(reverseAudit);if(error)auditWarning='Undo applied, but reverse audit failed: '+error.message}setData(d=>({...d,products:d.products.map(p=>{const old=bulkUndo.before.find(x=>x.id===p.id);return old?{...p,...old.values}:p})}));setBulkUndo(null);notify(auditWarning||'Bulk edit undone')};
 const openProduct=async p=>{if(role==='owner'&&supabase){const [{data:adjustments},{data:changes}]=await Promise.all([supabase.from('stock_adjustments').select('*').eq('product_id',p.id).order('created_at',{ascending:false}).limit(30),supabase.from('product_changes').select('*').eq('product_id',p.id).order('created_at',{ascending:false}).limit(30)]);setStockAdjustments(adjustments||[]);setProductChanges(changes||[])}else{setStockAdjustments([]);setProductChanges([])}setSelected(p);setForm({name:p.name,category:p.category,mrp:String(p.mrp??''),selling_price:String(p.selling_price??p.mrp??''),cost_price:p.cost_price??'',default_supplier_id:p.default_supplier_id??'',barcode:p.barcode||'',low_stock_limit:p.low_stock_limit??5,unit_type:p.unit_type||'piece',mfg_date:'',expiry_date:'',units:''});setScreen('Product detail')};
 const categoryPalette=['#dff1e5','#e9e4fb','#fff0d9','#dff1f4','#fde4e6','#e6ecd6'];const categoryColor=cat=>{let h=0;for(const c of String(cat||''))h=(h*31+c.charCodeAt(0))|0;return categoryPalette[Math.abs(h)%categoryPalette.length]};const productCard=p=><div className="product-card-wrap" key={p.id}>{selectMode&&role==='owner'&&<input aria-label={`Select ${p.name}`} type="checkbox" checked={bulkSelection.includes(p.id)} onChange={e=>setBulkSelection(ids=>e.target.checked?[...new Set([...ids,p.id])]:ids.filter(id=>id!==p.id))}/>}<button className="product-card" onClick={()=>selectMode&&role==='owner'?setBulkSelection(ids=>ids.includes(p.id)?ids.filter(id=>id!==p.id):[...ids,p.id]):openProduct(p)}><div className="product-icon category-icon" style={{backgroundColor:categoryColor(p.category),color:'#244d39'}}>{(p.category||p.name||'?').trim().slice(0,1).toUpperCase()}</div><div className="prod-main"><strong>{p.name}{p.hidden?' · Hidden':''}</strong><span>{p.category} · {allUnits(p)} {p.unit_type==='piece'?'units':p.unit_type}</span>{productStatusTags(p)}</div><div className="prod-price"><b>{fmt(sellPrice(p))}</b>{Number(p.mrp)>sellPrice(p)&&<small><s>{fmt(p.mrp)}</s> MRP · saves {savesPercent(p.mrp,sellPrice(p)).toFixed(0)}%</small>}{role==='owner'&&p.cost_price!=null&&<small className="owner-profit-chip">Profit {fmt(unitProfit(sellPrice(p),p.cost_price))}</small>}</div><ChevronRight className="card-arrow" size={17}/></button></div>;
